import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import {
  LineChart, Line, XAxis, YAxis,
  CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import {
  Shield, Plus, Bell, RefreshCw,
  AlertTriangle, CheckCircle, XCircle,
  Trash2, X, TrendingUp
} from 'lucide-react';
import './App.css';

const API = 'http://127.0.0.1:8000';

// ── Helper: get color class from score ───────────────────────
function getRiskClass(score) {
  if (score === null || score === undefined) return 'none';
  if (score >= 61) return 'red';
  if (score >= 31) return 'yellow';
  return 'green';
}

function getRiskIcon(level) {
  if (level === 'RED') return <XCircle size={14} />;
  if (level === 'YELLOW') return <AlertTriangle size={14} />;
  return <CheckCircle size={14} />;
}

// ── Risk Report Modal ─────────────────────────────────────────
function RiskModal({ data, onClose }) {
  if (!data) return null;
  const cls = getRiskClass(data.risk_score);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <h2>
          <span>{data.vendor_name} — Risk Report</span>
          <button className="modal-close" onClick={onClose}>
            <X size={18} />
          </button>
        </h2>

        {/* Score */}
        <div style={{ textAlign: 'center', marginBottom: 24 }}>
          <div style={{ fontSize: 64, fontWeight: 700 }}
            className={`score-number`}
            style={{
              fontSize: 64, fontWeight: 700,
              color: cls === 'red' ? '#f87171'
                : cls === 'yellow' ? '#fbbf24' : '#34d399'
            }}>
            {data.risk_score}
          </div>
          <div style={{ fontSize: 14, color: '#94a3b8' }}>
            Risk Score out of 100
          </div>
          <div className={`risk-badge ${cls}`} style={{ margin: '10px auto', width: 'fit-content' }}>
            {getRiskIcon(data.risk_level)} {data.risk_level}
          </div>
        </div>

        {/* Summary */}
        <div className="modal-section">
          <h3>Summary</h3>
          <div className="finding-item">{data.summary}</div>
        </div>

        {/* Key Findings */}
        <div className="modal-section">
          <h3>Key Findings ({data.key_findings?.length || 0})</h3>
          {data.key_findings?.map((f, i) => (
            <div key={i} className="finding-item">• {f}</div>
          ))}
        </div>

        {/* Risk Categories */}
        <div className="modal-section">
          <h3>Risk Breakdown</h3>
          <div className="category-grid">
            {Object.entries(data.risk_categories || {}).map(([k, v]) => (
              <div key={k} className="category-item">
                <div className="cat-label">
                  {k.replace('_risk', '').replace('_', ' ')}
                </div>
                <div className="cat-score" style={{
                  color: v >= 61 ? '#f87171'
                    : v >= 31 ? '#fbbf24' : '#34d399'
                }}>
                  {v}/100
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Recommended Actions */}
        <div className="modal-section">
          <h3>Recommended Actions</h3>
          {data.recommended_actions?.map((a, i) => (
            <div key={i} className="action-item">→ {a}</div>
          ))}
        </div>

        {/* Signals found */}
        <div style={{ fontSize: 12, color: '#64748b', textAlign: 'center' }}>
          {data.signals_found} signals collected •
          Confidence: {data.confidence_level} •
          Previous score: {data.previous_score}
        </div>
      </div>
    </div>
  );
}

// ── Main App ──────────────────────────────────────────────────
export default function App() {
  const [vendors, setVendors] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [showAlerts, setShowAlerts] = useState(false);
  const [scanningId, setScanningId] = useState(null);
  const [modalData, setModalData] = useState(null);
  const [historyData, setHistoryData] = useState({});
  const [form, setForm] = useState({
    name: '', website: '', industry: ''
  });
  const [adding, setAdding] = useState(false);

  // Load vendors and alerts
  const loadVendors = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/vendors`);
      setVendors(res.data.vendors);
    } catch (e) { console.error(e); }
  }, []);

  const loadAlerts = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/alerts`);
      setAlerts(res.data.alerts);
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    loadVendors();
    loadAlerts();
  }, [loadVendors, loadAlerts]);

  // Add vendor
  const addVendor = async () => {
    if (!form.name.trim()) return;
    setAdding(true);
    try {
      await axios.post(`${API}/vendors`, form);
      setForm({ name: '', website: '', industry: '' });
      await loadVendors();
    } catch (e) { console.error(e); }
    setAdding(false);
  };

  // Delete vendor
  const deleteVendor = async (id) => {
    if (!window.confirm('Delete this vendor?')) return;
    try {
      await axios.delete(`${API}/vendors/${id}`);
      await loadVendors();
    } catch (e) { console.error(e); }
  };

  // Scan vendor
  const scanVendor = async (vendor) => {
    setScanningId(vendor.id);
    try {
      const res = await axios.post(`${API}/vendors/${vendor.id}/scan`);
      setModalData(res.data);
      await loadVendors();
      await loadAlerts();
      // Load history for timeline
      const hist = await axios.get(`${API}/vendors/${vendor.id}/history`);
      setHistoryData(prev => ({
        ...prev,
        [vendor.id]: hist.data.history
      }));
    } catch (e) { console.error(e); }
    setScanningId(null);
  };

  // Stats
  const totalVendors = vendors.length;
  const redCount = vendors.filter(v => v.latest_score >= 61).length;
  const yellowCount = vendors.filter(
    v => v.latest_score >= 31 && v.latest_score < 61
  ).length;
  const greenCount = vendors.filter(
    v => v.latest_score !== null && v.latest_score < 31
  ).length;

  return (
    <div className="app">
      {/* NAVBAR */}
      <nav className="navbar">
        <div className="navbar-brand">
          <Shield size={24} color="#60a5fa" />
          <h1>VendorGuard AI</h1>
          <span>LIVE</span>
        </div>
        <button
          className="navbar-alerts"
          onClick={() => setShowAlerts(!showAlerts)}
        >
          <Bell size={16} />
          Alerts
          {alerts.length > 0 && (
            <span className="alert-badge">{alerts.length}</span>
          )}
        </button>
      </nav>

      <div className="main-content">

        {/* STATS ROW */}
        <div className="stats-row">
          <div className="stat-card">
            <div className="stat-label">Total Vendors</div>
            <div className="stat-value">{totalVendors}</div>
            <div className="stat-sub">Being monitored</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">🔴 Critical Risk</div>
            <div className="stat-value" style={{ color: '#f87171' }}>
              {redCount}
            </div>
            <div className="stat-sub">Score 61-100</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">🟡 Medium Risk</div>
            <div className="stat-value" style={{ color: '#fbbf24' }}>
              {yellowCount}
            </div>
            <div className="stat-sub">Score 31-60</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">🟢 Low Risk</div>
            <div className="stat-value" style={{ color: '#34d399' }}>
              {greenCount}
            </div>
            <div className="stat-sub">Score 0-30</div>
          </div>
        </div>

        {/* ALERTS PANEL */}
        {showAlerts && alerts.length > 0 && (
          <div className="alerts-panel">
            <h2>🔔 Recent Alerts</h2>
            {alerts.map(a => (
              <div key={a.id} className={`alert-item ${a.severity}`}>
                <div>
                  <div>{a.message}</div>
                  <div className="alert-time">
                    {new Date(a.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ADD VENDOR */}
        <div className="add-vendor-section">
          <h2>+ Monitor a New Vendor</h2>
          <div className="add-vendor-form">
            <input
              placeholder="Company name (e.g. Stripe)"
              value={form.name}
              onChange={e => setForm({ ...form, name: e.target.value })}
              onKeyDown={e => e.key === 'Enter' && addVendor()}
            />
            <input
              placeholder="Website (e.g. https://stripe.com)"
              value={form.website}
              onChange={e => setForm({ ...form, website: e.target.value })}
            />
            <input
              placeholder="Industry (e.g. Payments)"
              value={form.industry}
              onChange={e => setForm({ ...form, industry: e.target.value })}
            />
            <button
              className="btn-primary"
              onClick={addVendor}
              disabled={adding || !form.name.trim()}
            >
              <Plus size={16} />
              {adding ? 'Adding...' : 'Add Vendor'}
            </button>
          </div>
        </div>

        {/* VENDORS TABLE */}
        <div className="vendors-section">
          <h2>📊 Vendor Risk Dashboard</h2>
          {vendors.length === 0 ? (
            <div className="empty-state">
              <Shield size={48} color="#2d3748" />
              <p>No vendors yet. Add your first vendor above.</p>
            </div>
          ) : (
            <table className="vendor-table">
              <thead>
                <tr>
                  <th>Vendor</th>
                  <th>Industry</th>
                  <th>Risk Score</th>
                  <th>Status</th>
                  <th>Last Scanned</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {vendors.map(vendor => {
                  const cls = getRiskClass(vendor.latest_score);
                  const isScanning = scanningId === vendor.id;
                  const history = historyData[vendor.id] || [];

                  return (
                    <tr key={vendor.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{vendor.name}</div>
                        <div style={{ fontSize: 12, color: '#64748b' }}>
                          {vendor.website}
                        </div>
                      </td>
                      <td style={{ color: '#94a3b8' }}>
                        {vendor.industry || '—'}
                      </td>
                      <td>
                        {vendor.latest_score !== null ? (
                          <div className="score-bar-wrap">
                            <div className="score-bar">
                              <div
                                className={`score-bar-fill ${cls}`}
                                style={{ width: `${vendor.latest_score}%` }}
                              />
                            </div>
                            <span className="score-number"
                              style={{
                                color: cls === 'red' ? '#f87171'
                                  : cls === 'yellow' ? '#fbbf24' : '#34d399'
                              }}>
                              {vendor.latest_score}
                            </span>
                          </div>
                        ) : (
                          <span style={{ color: '#4a5568', fontSize: 13 }}>
                            Not scanned
                          </span>
                        )}
                        {/* Mini timeline */}
                        {history.length > 1 && (
                          <div style={{ height: 40, marginTop: 4 }}>
                            <ResponsiveContainer width="100%" height={40}>
                              <LineChart data={history}>
                                <Line
                                  type="monotone"
                                  dataKey="score"
                                  stroke={
                                    cls === 'red' ? '#f87171'
                                      : cls === 'yellow' ? '#fbbf24'
                                        : '#34d399'
                                  }
                                  dot={false}
                                  strokeWidth={2}
                                />
                              </LineChart>
                            </ResponsiveContainer>
                          </div>
                        )}
                      </td>
                      <td>
                        {isScanning ? (
                          <span className="scanning-text">
                            <RefreshCw size={12} /> Scanning...
                          </span>
                        ) : vendor.latest_score !== null ? (
                          <span className={`risk-badge ${cls}`}>
                            {getRiskIcon(
                              cls === 'red' ? 'RED'
                                : cls === 'yellow' ? 'YELLOW' : 'GREEN'
                            )}
                            {cls.toUpperCase()}
                          </span>
                        ) : (
                          <span className="risk-badge none">PENDING</span>
                        )}
                      </td>
                      <td style={{ fontSize: 12, color: '#64748b' }}>
                        {vendor.last_scanned
                          ? new Date(vendor.last_scanned).toLocaleString()
                          : 'Never'
                        }
                      </td>
                      <td>
                        <button
                          className="btn-scan"
                          onClick={() => scanVendor(vendor)}
                          disabled={isScanning}
                        >
                          <RefreshCw size={12} />
                          {isScanning ? 'Scanning...' : 'Scan Now'}
                        </button>
                        <button
  className="btn-scan"
  style={{ marginLeft: 8, background: '#1a2e1a', 
           borderColor: '#34d399', color: '#34d399' }}
  onClick={() => window.open(
    `${API}/vendors/${vendor.id}/pdf`, '_blank'
  )}
  disabled={!vendor.latest_score}
>
  📄 PDF
</button>

                        <button
                          className="btn-delete"
                          onClick={() => deleteVendor(vendor.id)}
                          disabled={isScanning}
                        >
                          <Trash2 size={12} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* RISK REPORT MODAL */}
      {modalData && (
        <RiskModal
          data={modalData}
          onClose={() => setModalData(null)}
        />
      )}
    </div>
  );
}
